  subject?: string;
  claim?: string;
  boundary?: 'repo' | 'global';
  repoId?: string;
  appliesTo?: string[];
  trust?: Verdicts['trust'];
  verdicts?: Partial<Verdicts>;
  createdAt?: string;
  kind?: MemoryRecordKind;
  evidenceItems?: MemoryEvidence[];
}): MemoryRecord

